#Idea to solve this challenge: https://di-mgt.com.au/rsa_factorize_n.html
from Crypto.Util.number import long_to_bytes
import random
import math

def factor_from_ed(N, e, d):
    k = e * d - 1
    t = 0
    r = k
    while r % 2 == 0:
        r //= 2
        t += 1

    while True:
        g = random.randrange(2, N - 1)
        x = pow(g, r, N)
        if x == 1 or x == N - 1:
            continue

        for _ in range(t):
            y = math.gcd(x - 1, N)
            if 1 < y < N:
                return y, N // y
            x = pow(x, 2, N)
            if x == 1:
                break

